loops.kickoffPrompt:
{
  "loop": "pr-babysitter",
  "goal": "Keep one pull request moving toward merge-ready without a human polling comments, CI, conflicts, and stale review threads.",
  "when": { "on": "schedule", "fires": "every 2 hours in working hours, plus on requested changes or a failed required check" },
  "pick_work": "Act only on explicit blockers: unresolved review comments, failed checks, merge conflicts, or stale reviewer state.",
  "sandbox": {
    "where": "a dedicated worktree off the PR branch",
    "never": ["force-push", "large refactor", "dependency upgrade", "secrets access", "production change"]
  },
  "checks": ["required GitHub checks pass", "every unresolved comment is answered or resolved", "the diff stays scoped to the blocker"],
  "memory": "pr-babysitter-state.md: attempts per PR, last action, open blockers",
  "limits": { "max_turns": 3, "max_minutes": 60 },
  "hand_off": {
    "when": ["an architectural decision is needed", "the same failure repeats twice", "reviewers disagree", "a force-push would be required"],
    "to": "a PR comment that tags the human owner"
  },
  "done": {
    "success": "the PR is merge-ready or waiting only on human review",
    "give_up": "the loop is blocked, the budget is spent, or the next step needs human judgment"
  }
}

{
  "loop": "ci-repair",
  "goal": "Turn a failing CI signal into a small verified fix or a precise escalation note.",
  "when": { "on": "event", "fires": "a required CI check fails on an active pull request" },
  "pick_work": "Only failures with a reproducible command or a clear log-backed cause.",
  "sandbox": {
    "where": "a worktree off the failing branch",
    "never": ["weaken assertions", "delete tests", "broad reformatting", "unrequested dependency upgrade"]
  },
  "checks": ["the original failing command now passes", "the patch is limited to the failure's cause", "new behavior gets a focused test when one is warranted"],
  "memory": "a PR comment trail: the failing log excerpt, the patch, the passing output",
  "limits": { "max_turns": 3, "max_minutes": 90 },
  "hand_off": {
    "when": ["credentials are missing", "a third-party outage", "the failure is nondeterministic", "the fix exceeds scope"],
    "to": "a PR comment requesting a human reviewer"
  },
  "done": {
    "success": "the target check passes locally or on rerun CI",
    "give_up": "the failure is flaky, not reproducible, environment-blocked, or needs owner approval"
  }
}

{
  "loop": "incident-response",
  "goal": "Turn a fresh alert into a triaged, evidence-backed incident with a clear owner and a postmortem trail.",
  "when": { "on": "event", "fires": "a pager alert fires or an error-budget burn crosses a threshold; then refresh every 2-5 minutes while the incident is open" },
  "pick_work": "Correlate the alert with deploys, logs, traces, and metrics. Diagnose only.",
  "sandbox": {
    "where": "read-only access to observability, change logs, and pager state; no remediation surface",
    "never": ["roll back", "restart services", "change config", "run any remediation"]
  },
  "checks": ["severity is backed by concrete impact evidence", "the suspected cause cites specific deploys, logs, traces, or metrics", "missing telemetry is reported as unknown, never as healthy"],
  "memory": "an incident timeline: alert, evidence, hypotheses, owner, handoff time",
  "limits": { "max_minutes": 15 },
  "hand_off": {
    "when": ["a customer-facing outage", "data-loss risk", "a security signal", "missing telemetry", "mitigation needs a production action"],
    "to": "the on-call owner, via pager, with the evidence timeline"
  },
  "done": {
    "success": "the incident is triaged with severity, suspected cause, and an owner",
    "give_up": "evidence is insufficient or any fix would require touching production"
  }
}

{
  "loop": "dependency-triage",
  "goal": "Sort dependency updates into safe patches, deferred upgrades, and human-review items, each with reproducible evidence.",
  "when": { "on": "schedule", "fires": "weekly, plus on any security advisory for a package in use" },
  "pick_work": "Bucket updates by risk (safe patch, minor feature, major migration, security, blocked). Act automatically only on the safe-patch bucket.",
  "sandbox": {
    "where": "a worktree per update group",
    "never": ["major version migrations", "runtime version changes", "security-policy changes", "broad multi-group upgrades"]
  },
  "checks": ["lockfile and manifest stay consistent", "relevant tests, typecheck, build, and audit pass", "no changelog-named migration step is skipped"],
  "memory": "dependency-triage-state.md: each update's bucket, decision, and reason",
  "limits": { "max_turns": 2, "max_minutes": 45 },
  "hand_off": {
    "when": ["a major version upgrade", "a runtime requirement change", "a security advisory with product impact", "a licensing concern"],
    "to": "an issue or PR comment with the per-bucket reasons"
  },
  "done": {
    "success": "safe patches are applied and verified; everything riskier is filed with reasons",
    "give_up": "any update needs a migration plan or a human risk decision"
  }
}

{
  "loop": "pr-review",
  "goal": "Give every opened PR a substantive, evidence-backed first review without a human reviewer polling the queue.",
  "when": { "on": "event", "fires": "a pull request is opened or pushed to" },
  "pick_work": "Review the diff only; never the whole repo. Skip vendored/generated paths.",
  "sandbox": {
    "where": "read-only checkout of the PR head; no write surface",
    "never": ["push commits", "approve or merge", "request changes as a human", "edit the branch"]
  },
  "checks": ["each finding cites a specific file and line", "each finding names a concrete failure mode, not a style preference", "the reviewer is a different model/agent than any that wrote the code"],
  "memory": "review comments on the PR itself; a per-repo learnings file of recurring issues",
  "limits": { "max_minutes": 20 },
  "hand_off": {
    "when": ["a security-relevant change", "an architectural decision", "the diff exceeds a human-reviewable size"],
    "to": "a PR comment tagging a human reviewer, with the findings so far"
  },
  "done": {
    "success": "the PR has a posted review with concrete, located findings (or an explicit 'no issues found')",
    "give_up": "the diff is too large to review meaningfully, or needs human judgment"
  }
}

{
  "loop": "doc-drift",
  "goal": "Keep docs in sync with code: catch references to renamed/removed symbols, dead links, and stale examples, and fix the cheap ones.",
  "when": { "on": "schedule", "fires": "nightly, plus on merge to the default branch" },
  "pick_work": "Only docs whose referenced symbols, files, commands, or links no longer resolve. One doc per turn.",
  "sandbox": {
    "where": "a worktree off the default branch",
    "never": ["rewrite docs for tone/style", "change code to match the docs", "invent behavior the code doesn't have"]
  },
  "checks": ["every code reference in the changed doc resolves", "all links return 200", "any code example still runs / type-checks", "no behavioral claim was added that isn't in the code"],
  "memory": "doc-drift-state.md: each doc's last-verified commit and open drift items",
  "limits": { "max_turns": 3, "max_minutes": 30 },
  "hand_off": {
    "when": ["the drift implies a real behavior change to document", "the doc's intent is ambiguous", "a fix would require deciding what the feature should do"],
    "to": "an issue with the drift list and the ambiguous cases flagged"
  },
  "done": {
    "success": "broken references and links are fixed and verified; ambiguous drift is filed",
    "give_up": "the correct content requires a human product/intent decision"
  }
}

{
  "loop": "flaky-hunt",
  "goal": "Find and quarantine genuinely flaky tests (pass and fail on the same commit), with reproducible evidence, without masking real regressions.",
  "when": { "on": "schedule", "fires": "nightly; re-runs the suite N times on a pinned commit" },
  "pick_work": "Only tests that both pass and fail across repeated runs of the SAME commit. A test that fails every time is a real failure, not a flake.",
  "sandbox": {
    "where": "a worktree on a pinned commit; the test runner only",
    "never": ["delete a test", "weaken an assertion", "add a blanket retry to hide flakiness", "quarantine a test that fails deterministically"]
  },
  "checks": ["the test demonstrably both passed and failed on the same commit across runs", "the quarantine is annotated with the run evidence and an owner", "no deterministically-failing test was quarantined"],
  "memory": "flaky-state.md: per-test pass/fail counts across runs, quarantine decisions, evidence links",
  "limits": { "max_minutes": 60, "max_reruns": 20 },
  "hand_off": {
    "when": ["a 'flake' is actually a deterministic failure (a real bug)", "the flake rate is climbing across the suite", "the root cause is environmental/infra"],
    "to": "an issue with the per-test evidence and the suspected cause"
  },
  "done": {
    "success": "confirmed flakes are quarantined with evidence and an owner; real failures are filed as bugs, not hidden",
    "give_up": "the instability is environmental or points to a real regression needing a human"
  }
}
